sequence.script:

  var data = mc.getPayloadJSON();
  var employees = data.employees;
  var totalGross = 0;
  var totalTax = 0;
  var totalDeduction = 0;
  var totalNet = 0;
  var payrollStatus = "PROCESSED";
  for (var i = 0 ; i < employees.length; i++){
 totalGross += Number(employees[i].gross);
 totalTax += Number(employees[i].tax);
 totalDeduction += Number(employees[i].deduction);
  totalNet += Number(employees[i].net);
  if(employees[i].status !== "PROCESSED"){
payrollStatus = "REJECTED";
  }
  }
  mc.setProperty("totalGross",totalGross);
    mc.setProperty("totalTax",totalTax);
    mc.setProperty("totalDeduction",totalDeduction);
      mc.setProperty("totalNet",totalNet);
   mc.setProperty("payrollStatus",payrollStatus);
